"""JWT 발급/검증 (pyjwt, HS256)."""
import os
from app.ops.env import is_production
import time

import jwt


_DEFAULT_SECRET = "dev-secret-key-for-local-only-safe-and-long-enough"
_MIN_SECRET_LEN = 32
_ALG = "HS256"
_ISSUER = "saju-auth"




def _pytest_env_mode() -> str:
    """SAJU_ENV 를 반환. pytest 실행 중 SAJU_ENV 미설정이면 'test' 로 폴백.
    프로덕션 환경에는 PYTEST_CURRENT_TEST 가 존재하지 않으므로 fail-closed 유지."""
    env = os.environ.get("SAJU_ENV", "").strip().lower()
    if env:
        return env
    if os.environ.get("PYTEST_CURRENT_TEST"):
        return "test"
    return ""


def _secret() -> str:
    s = os.environ.get("SAJU_JWT_SECRET", "").strip()
    if not s:
        if is_production():
            raise RuntimeError("SAJU_JWT_SECRET is not set in production. Failing closed.")
        return _DEFAULT_SECRET
    if is_production() and len(s) < 32:
        raise RuntimeError("SAJU_JWT_SECRET must be at least 32 characters in production.")
    return s


def ttl_seconds() -> int:
    try:
        return int(os.environ.get("SAJU_JWT_TTL_SECONDS", str(60 * 60 * 24 * 30)))
    except ValueError:
        return 60 * 60 * 24 * 30


def encode_token(user_id: str) -> str:
    now = int(time.time())
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + ttl_seconds(),
        "iss": _ISSUER,
    }
    return jwt.encode(payload, _secret(), algorithm=_ALG)


def decode_token(token: str) -> dict:
    return jwt.decode(
        token, _secret(), algorithms=[_ALG], issuer=_ISSUER,
    )
